queries.source:
/// @ 1.2.1
// Bot のみクエリ — true = 表示
//
// Bot アカウントのノートだけに絞り込み、ニュースや RSS、観測 bot の投稿を
// まとめて眺めるカラムにする。組込のフィルタトグルは Bot を隠す向きだけ
// なので、その対になる。isBot を立てていない bot は通らない。
// note.user.isBot はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.user.isBot == true

/// @ 1.2.1
// しずかなタイムラインクエリ — true = 表示
//
// 純リノート・リプライ・冒頭 @ の呼びかけ・ダイレクト投稿をまとめて隠し、
// フォロイーが自分の言葉で書いたノートだけを流す。
// 冒頭が @ のノートは返信扱いでなくても誰かに宛てた会話なので隠す
// (文中に @ が出るだけの言及は通す)。
let is_pure_renote = note.renoteId != null && note.text == null
let is_reply = note.replyId != null
let is_mention = note.text != null && note.text.starts_with("@")
let is_direct = note.visibility == "specified"

!is_pure_renote && !is_reply && !is_mention && !is_direct

/// @ 1.2.1
// ねこのみクエリ — true = 表示
//
// ねこ (isCat) なユーザーのノートだけに絞り込む。
// note.user.isCat はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
// isCat が無いサーバー由来のノートは == の型不一致で false になるだけで
// per-note エラーにはならない。
note.user.isCat == true

/// @ 1.2.1
// チャンネルノートを隠すクエリ — true = 表示
//
// チャンネル投稿を隠し、ソーシャル / ローカル TL を通常ノートだけにする。
// yamisskey の excludeChannelNotesNonFollowing に近い使い心地を
// どのサーバーでも得るための近似 (フォロー中チャンネルの判別は
// コンテキスト述語 (notedeck#783 Phase 4) 待ちのため、全チャンネルを隠す)。
// note.channelId はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.channelId == null

/// @ 1.2.1
// チャンネルノートのみクエリ — true = 表示
//
// チャンネル投稿だけに絞り込み、ソーシャル / ホーム TL に混ざる
// チャンネルの流れだけを 1 つのカラムに取り出す。channel-hide の対。
// どのチャンネルかは問わない (特定チャンネルはチャンネルカラムを使う)。
// note.channelId はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.channelId != null

/// @ 1.2.1
// 返信が集まるノートクエリ — true = 表示
//
// 返信が 3 件以上ついたノートだけに絞り、会話や議論が盛り上がっている
// ノートを追う。しきい値は末尾の数字を書き換えて使う。
// 返信そのものではなく「返信を集めている元ノート」が通る点が
// 組込のリプライ表示トグルとの違い。
// note.repliesCount はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.repliesCount != null && note.repliesCount >= 3

/// @ 1.2.1
// 他人への返信を隠すクエリ — true = 表示
//
// 返信のうち、他人のノートに向けたものだけを隠す。自分のノートに続けた
// 返信 (スレッド・連投) は投稿者が同じなので残る。組込のリプライ非表示
// トグルはスレッドも消してしまうため、その精密版。
// 返信元の情報 (note.reply) が届いていない返信は判定できないので隠す。
// note.reply はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
let is_reply = note.replyId != null
let same_user = note.reply != null && note.reply.user != null && note.reply.user.username == note.user.username
let same_host = note.reply != null && note.reply.user != null && note.reply.user.host == note.user.host

!is_reply || (same_user && same_host)

/// @ 1.2.1
// ハッシュタグ付きを隠すクエリ — true = 表示
//
// ハッシュタグを含むノートを、リノート先の本文も含めて隠す。
// yamisskey の withHashtags=false 相当をどのサーバーでも得るための近似。
// サーバーが解析したタグ一覧 (note.tags) は届かないため本文の "#" で
// 判定する (URL のフラグメント等も稀に巻き込む)。
// note.renote はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
let has_tag = note.text != null && note.text.incl("#")
let renote_has_tag = note.renote != null && note.renote.text != null && note.renote.text.incl("#")
!has_tag && !renote_has_tag

/// @ 1.2.1
// ハッシュタグ購読クエリ — true = 表示
//
// 指定ハッシュタグを含むノートだけを流すテンプレート。
// hit 内の incl の並びを書き換えて自分のタグリストにする。
@hit(lowered) {
	lowered.incl("#技術書典") || lowered.incl("#photomisskey")
}

note.text != null && hit(note.text.lower())

/// @ 1.2.1
// キーワード発掘クエリ — true = 表示
//
// 単一キーワードを含むノートだけを流す高速版テンプレート。
// キーワードを 3 文字以上にすると全文検索インデックス (FTS) が効き、
// キャッシュ検索でも高速に遡れる。lower() を挟むと FTS が効かなくなる
// ため、大小文字を無視したい英語キーワードは topic-watch を使う。
note.text != null && note.text.incl("ノートデック")

/// @ 1.2.1
// キーワード非表示クエリ — true = 表示
//
// このカラムだけ NG ワードを含むノートを隠すテンプレート。
// hit 内の incl の並びを書き換えて自分のリストにする。
// アカウント全体で隠したい語は本体設定のワードミュートを使う
// (あちらは全カラム + 通知に効く。こちらはカラム単位の視界定義)。
@hit(lowered) {
	lowered.incl("懸賞") || lowered.incl("プレゼント企画") || lowered.incl("拡散希望")
}

!(note.text != null && hit(note.text.lower())) && !(note.cw != null && hit(note.cw.lower()))

/// @ 1.2.1
// リンク付きのみクエリ — true = 表示
//
// URL を含むノートだけに絞り込み、記事やニュースの共有を拾うカラムにする。
note.text != null && note.text.lower().incl("http")

/// @ 1.2.1
// ローカルのみクエリ — true = 表示
//
// リモートユーザーのノートを隠し、自サーバーのユーザーだけに絞る。
// ローカルユーザーは host が null になる。
note.user.host == null

/// @ 1.2.1
// 長文を隠すクエリ — true = 表示
//
// 本文が 300 文字以上のノートを隠し、長文の連投や MFM アートで
// カラムが埋まるのを防ぐ。しきい値は末尾の数字を書き換えて使う。
// 本文のないノート (純リノート・添付のみ) はそのまま通す。
// 文字列の len はサブセット外のため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.text == null || note.text.len < 300

/// @ 1.2.1
// 長文のみクエリ — true = 表示
//
// 本文が 300 文字以上のノートだけに絞り込み、じっくり読む読み物の
// カラムにする。long-hide の対。しきい値は末尾の数字を書き換えて使う。
// 文字列の len はサブセット外のため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.text != null && note.text.len >= 300

/// @ 1.2.1
// CW 付きを隠すクエリ — true = 表示
//
// CW (内容警告) つきのノートを、このカラムでは畳まずまるごと隠す。
note.cw == null

/// @ 1.2.1
// 連合なしのみクエリ — true = 表示
//
// 連合に配送されないノート (ローカル限定投稿) だけに絞り込む。
// サーバー内だけの内輪の話題を追うカラムにする。
note.localOnly == true

/// @ 1.2.1
// リンク付きを隠すクエリ — true = 表示
//
// URL を含むノートを隠し、宣伝や自動投稿でカラムが埋まるのを防ぐ。
// 本文が無いノート (メディアのみ・純リノート) はそのまま通す。
!(note.text != null && note.text.lower().incl("http"))

/// @ 1.2.1
// 非公開ノートのみクエリ — true = 表示
//
// フォロワー限定・ダイレクトのノートだけに絞り込む。
// 流速の速いホーム TL で内輪の投稿を見逃さないためのカラムにする。
note.visibility == "followers" || note.visibility == "specified"

/// @ 1.2.1
// アンケートのみクエリ — true = 表示
//
// アンケート (投票) つきのノートだけに絞り込み、投票して回るカラムにする。
// note.poll はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.poll != null

/// @ 1.2.1
// 公開ノートのみクエリ — true = 表示
//
// 公開ノートだけに絞る。ホーム TL やリストからホーム限定・
// フォロワー限定・ダイレクトを外し、引用や共有をしてよい
// ノートだけが流れるカラムにする (「非公開ノートのみ」の対)。
note.visibility == "public"

/// @ 1.2.1
// 引用のみクエリ — true = 表示
//
// 本文つきのリノート (引用) だけに絞り込む。
// 話題へのコメントや反応だけを追うカラムにする。
note.renoteId != null && note.text != null

/// @ 1.2.1
// リアクション済みを隠すクエリ — true = 表示
//
// 自分がリアクションしたノートを隠す。リアクションを既読印として使うと、
// まだ目を通していないノートだけが残る受信箱のようなカラムになる。
// 判定はカラムのアカウントから見た myReaction なので、別アカウントでの
// リアクションは反映されない。
// note.myReaction はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.myReaction == null

/// @ 1.2.1
// リアクションで絞るクエリ — true = 表示
//
// 指定した絵文字のリアクションが 3 件以上ついたノートだけに絞る。
// hit のしきい値と末尾の絵文字を書き換えて使う
// (カスタム絵文字は ":name@host:" 表記。リモートは ":name@example.com:")。
// reactions が null のノートは && の短絡で hit を評価しないので、
// リアクション 0 のノートが per-note エラーにならない。この順番は変えない。
@hit(count) {
	count != null && count >= 3
}

note.reactions != null && hit(note.reactions["👍"])

/// @ 1.2.1
// リモートのみクエリ — true = 表示
//
// 自サーバーのユーザーを隠し、連合先のノートだけに絞る。
// ローカルユーザーは host が null になる (「ローカルのみ」の対)。
note.user.host != null

/// @ 1.2.1
// リノートで絞るクエリ — true = 表示
//
// リノートが 3 件以上ついたノートだけに絞り、広く拡散されている話題だけを追う。
// しきい値は末尾の数字を書き換えて使う。reaction-boost は絵文字別の反応量、
// こちらは絵文字を問わない拡散量で見る。
// 純リノート自身の renoteCount は 0 なので、拡散元のノートが流れてきたときだけ通る。
// note.renoteCount はサブセット外フィールドのため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
note.renoteCount != null && note.renoteCount >= 3

/// @ 1.2.1
// 特定サーバーを隠すクエリ — true = 表示
//
// 指定サーバーのユーザーのノートを隠すテンプレート。
// blocked 内の並びを書き換えて自分のリストにする。
// ends_with を使うと "a.example.com" "b.example.com" のような
// サブドメイン群をまとめて隠せる (ドット付きで書き、本体は == で別に挙げる)。
// ローカルユーザー (host == null) は常に通す。
@blocked(host) {
	host == "example.com" || host.ends_with(".example.com") || host == "spam.example"
}

note.user.host == null || !blocked(note.user.host)

/// @ 1.2.1
// 特定サーバーのみクエリ — true = 表示
//
// 指定サーバーのユーザーのノートだけに絞り込むテンプレート。
// グローバル TL やリストから特定サーバーの流れだけを取り出す。
// 自サーバーに絞るときは「ローカルのみ」を使う (ローカルは host が null)。
note.user.host == "misskey.io"

/// @ 1.2.1
// スパムらしき投稿を隠すクエリ — true = 表示
//
// 連合スパムの典型形「リモートから、誰かに @ を飛ばしつつリンクを貼る」
// 「表示名を設定していないアカウントがリンクを貼る」を近似で隠す。
// 本文のキーワードに依存しないので、文言が変わる波にも効く。
// ローカルユーザーは常に通し、リンクのない投稿も常に通す。
// 表示名を設定していないだけの正規ユーザーのリンク投稿も巻き込むので、
// 平時は無効にし、スパムの波が来たときだけ有効にする使い方が合う。
let remote = note.user.host != null
let has_link = note.text != null && note.text.lower().incl("http")
let has_mention = note.text != null && note.text.incl("@")
let no_name = note.user.name == null

!(remote && has_link && (has_mention || no_name))

/// @ 1.2.1
// テキストのみクエリ — true = 表示
//
// 添付ファイルのあるノートを隠し、文字だけの読み物タイムラインにする。
// files が無いノートも安全に通す (null ガード)。
note.files == null || note.files.len == 0

/// @ 1.2.1
// キーワード購読クエリ — true = 表示
//
// 指定キーワードを含むノートだけを流す購読カラムのテンプレート。
// hit 内の incl の並びを書き換えて自分の話題リストにする。
// アンテナと違いサーバー側の設定が不要で、既存のどのカラムにも重ねられる。
@hit(lowered) {
	lowered.incl("notedeck") || lowered.incl("misskey")
}

(note.text != null && hit(note.text.lower())) || (note.cw != null && hit(note.cw.lower()))

/// @ 1.2.1
// 特定ユーザーを隠すクエリ — true = 表示
//
// 指定ユーザーのノートをこのカラムだけで隠すテンプレート。
// blocked 内の並びを書き換えて自分のリストにする (username は小文字で書く)。
// username だけを見るので、同名のリモートユーザーも一緒に隠れる。
// アカウント全体で隠すなら本体のミュート/ブロックを使う
// (あちらは全カラム + 通知に効く。こちらはカラム単位の視界定義)。
@blocked(name) {
	name == "example_user" || name == "noisy_account"
}

!blocked(note.user.username.lower())

/// @ 1.2.1
// 特定ユーザーのみクエリ — true = 表示
//
// 指定ユーザーのノートだけに絞り込むテンプレート。user-hide の対。
// hit 内の並びを書き換えて自分のリストにする
// (host はローカルユーザーなら null、リモートは "example.com")。
@hit(username, host) {
	(username == "alice" && host == null) || (username == "bob" && host == "misskey.io")
}

hit(note.user.username, note.user.host)

/// @ 1.2.1
// 動画付きのみクエリ — true = 表示
//
// 動画ファイルが添付されたノートだけに絞り込む。組込の「メディアのみ」
// トグルは画像も通すので、その細分として動画だけを流すカラムにする。
// 純リノートは本体に添付がないので、リノート先の添付も見る。
// 判定は MIME タイプの先頭 "video/" で、音声だけなら "audio/" に、
// 画像だけなら "image/" に書き換えて使える。
// note.files の要素と note.renote はサブセット外のため 🐢 逐次適用になり、
// キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
let own = note.files != null && note.files.some(@(f) { f.type != null && f.type.starts_with("video/") })
let via = note.renote != null && note.renote.files != null && note.renote.files.some(@(f) { f.type != null && f.type.starts_with("video/") })
own || via

/// @ 1.2.1
// やみノートを隠すクエリ — true = 表示
//
// yamisskey のやみモード (isNoteInYamiMode) で投稿されたノートを隠し、
// 通常のカラムには昼のノートだけを流す。やみノートはやみ TL カラムで読む。
// フラグを持たないサーバーのノートは常に通る。
// フォーク固有のモードフラグ (note.modeFlags) はサブセット外のため
// 🐢 逐次適用になり、キャッシュ検索・高速検索は使えない (1 件ずつ判定)。
!(note.modeFlags != null && note.modeFlags["isNoteInYamiMode"] == true)
